import { assign } from './util';
import { createVNode } from './create-element';

/**
 * Clones the given VNode, optionally adding attributes/props and replacing its children.
 * @param {import('./internal').VNode} vnode The virtual DOM element to clone
 * @param {object} props Attributes/props to add when cloning
 * @param {Array<import('./internal').ComponentChildren>} rest Any additional arguments will be used as replacement children.
 * @returns {import('./internal').VNode}
 */
export function cloneElement(vnode, props, children) {
	let normalizedProps = assign({}, vnode.props),
		key,
		ref,
		i;
	for (i in props) {
		if (i == 'key') key = props[i];
		else if (i == 'ref') ref = props[i];
		else normalizedProps[i] = props[i];
	}

	if (arguments.length > 3) {
		children = [children];
		for (i = 3; i < arguments.length; i++) {
			children.push(arguments[i]);
		}
	}
	if (children != null) {
		normalizedProps.children = children;
	}

	return createVNode(
		vnode.type,
		normalizedProps,
		key || vnode.key,
		ref || vnode.ref,
		null
	);
}

/**
 * @param {import('./internal').PreactElement} parentDom
 * @param {import('./internal').PreactElement} oldDom
 */
export function ChildOrder(parentDom, oldDom) {
	this._parentDom = parentDom;
	this._oldDom = oldDom;
}

/**
 * Reorder DOM nodes for a vnode whose children were reused (for example after
 * a shouldComponentUpdate bailout).
 * @param {import('./internal').VNode} childVNode
 * @returns {import('./internal').PreactElement}
 */
ChildOrder.prototype.reorderChildren = function(childVNode) {
	let owner = childVNode._component;
	let parentDom = this._parentDom;
	let oldDom = this._oldDom;
	let children = childVNode._children;

	if (owner != null && owner._parentDom === parentDom) {
		parentDom = owner._parentDom;
	}
	if (owner != null && owner.base === oldDom) {
		oldDom = owner.base;
	}

	for (let tmp = 0; tmp < children.length; tmp++) {
		let vnode = children[tmp];
		if (vnode) {
			vnode._parent = childVNode;

			if (typeof vnode.type == 'function') {
				new ChildOrder(parentDom, oldDom).reorderChildren(vnode);
			} else {
				let newDom = vnode._dom;
				let nextDom;
				if (vnode._nextDom !== undefined) {
					nextDom = vnode._nextDom;
					vnode._nextDom = undefined;
				} else if (newDom != oldDom || newDom.parentNode == null) {
					outer: if (oldDom == null || oldDom.parentNode !== parentDom) {
						parentDom.appendChild(newDom);
						nextDom = null;
					} else {
						for (
							let sibDom = oldDom, j = 0;
							(sibDom = sibDom.nextSibling) && j < children.length;
							j += 2
